def symbolic(mode):
    out = []
    for shift in (6, 3, 0):
        bits = (mode >> shift) & 7
        out.append("r" if bits & 4 else "-")
        out.append("w" if bits & 2 else "-")
        out.append("x" if bits & 1 else "-")
    if mode & 0o4000:
        out[2] = "s" if out[2] == "x" else "S"
    if mode & 0o2000:
        out[5] = "s" if out[5] == "x" else "S"
    if mode & 0o1000:
        out[8] = "t" if out[8] == "x" else "T"
    return "".join(out)
